<?php
declare(strict_types=1);
$root=dirname(__DIR__);$tables=['users','patients','appointments','clinical_records','clinical_documents','financial_transactions','therapeutic_tasks','mood_logs','patient_portal_users','ai_interactions','notification_queue','user_sessions','audit_logs'];
$allow=json_decode(file_get_contents($root.'/docs/security/tenant-query-allowlist.json'),true)?:[];$allowed=array_column($allow,'reason','file');$warnings=[];
$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));
foreach($it as $f){if($f->getExtension()!=='php')continue;$rel=str_replace('\\','/',str_replace($root.DIRECTORY_SEPARATOR,'',$f->getPathname()));if(str_starts_with($rel,'scripts/')||str_starts_with($rel,'tests/'))continue;if(isset($allowed[$rel]))continue;$code=file_get_contents($f->getPathname());foreach(token_get_all($code?:'') as $tok){if(!is_array($tok)||$tok[0]!==T_CONSTANT_ENCAPSED_STRING)continue;$s=$tok[1];if(str_contains($s,'SECURITY_SCOPE:GLOBAL'))continue;if(!preg_match('/\b(SELECT|INSERT|UPDATE|DELETE)\b/i',$s))continue;foreach($tables as $table){if(!preg_match('/\b'.preg_quote($table,'/').'\b/i',$s))continue;if(stripos($s,'tenant_id')===false && stripos($s,':tenant')===false && stripos($s,':t')===false){$warnings[]="$rel: SQL envolvendo $table sem referência explícita a tenant_id";break;}}}}
if($warnings){fwrite(STDERR,"[FAIL] Consultas tenant-owned sem escopo explícito:\n- ".implode("\n- ",array_unique($warnings))."\n");exit(1);}echo "[OK] Consultas tenant-owned cobertas ou justificadas no allowlist.\n";
